Here is the root cause:
In `nfc_unregister_device`, the function holds `device_lock(&dev->dev)` and then calls `rfkill_unregister` which acquires `rfkill_global_mutex`. Meanwhile, `rfkill_fop_write` holds `rfkill_global_mutex` and then calls into NFC callback `nfc_rfkill_set_block` which eventually acquires `device_lock`. This creates an ABBA deadlock due to inverted lock ordering.

Here is the patch:
  */
 void nfc_unregister_device(struct nfc_dev *dev)
 {
 	int rc;
+	struct rfkill *rfk = NULL;

 	pr_debug("dev_name=%s\n", dev_name(&dev->dev));

 	rc = nfc_genl_device_removed(dev);
 	if (rc)
 		pr_debug("The userspace won't be notified that the device %s "
 			 "was removed\n", dev_name(&dev->dev));

 	device_lock(&dev->dev);
 	if (dev->rfkill) {
-		rfkill_unregister(dev->rfkill);
-		rfkill_destroy(dev->rfkill);
+		rfk = dev->rfkill;
 		dev->rfkill = NULL;
 	}
 	dev->shutting_down = true;
 	device_unlock(&dev->dev);

+	if (rfk) {
+		rfkill_unregister(rfk);
+		rfkill_destroy(rfk);
+	}
+
 	if (dev->ops->check_presence) {
 		timer_delete_sync(&dev->check_pres_timer);
 		cancel_work_sync(&dev->check_pres_work);
 	}

 	nfc_llcp_unregister_device(dev);

 	mutex_lock(&nfc_devlist_mutex);
 	nfc_devlist_generation++;
 	device_del(&dev->dev);
 	mutex_unlock(&nfc_devlist_mutex);
 }
 EXPORT_SYMBOL(nfc_unregister_device);


